package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
	"time"
)

type Test struct {
	is    io.Reader
	out   *bufio.Writer
	INPUT string
	F     []int64

	inbuf  []byte
	lenbuf int
	ptrbuf int

	oj bool
}

func (t *Test) solve() {
	t.F = make([]int64, 17)
	t.F[0] = 1
	for i := 1; i <= 16; i++ {
		t.F[i] = t.F[i-1] * int64(i)
	}

	K := t.nl()
	tt := t.ni()
	K--

gouter:
	for length := 1; ; length++ {
		var ret int64 = 0
		rem := make([]int, 16)
		for i := range rem {
			rem[i] = tt
		}
	outer:
		for i := 0; i < length; i++ {
			start := 0
			if i == 0 {
				start = 1
			}
			for j := start; j < 16; j++ {
				rem[j]--
				count := t.count(rem, length-1-i)
				if K < count {
					ret = ret*16 + int64(j)
					continue outer
				} else {
					K -= count
				}
				rem[j]++
			}
			continue gouter
		}
		fmt.Fprintln(t.out, strconv.FormatUint(uint64(ret), 16))
		return
	}
}

func (t *Test) count(rem []int, length int) int64 {
	dp := make([]int64, length+1)
	dp[0] = t.F[length]
	for _, x := range rem {
		if x < 0 {
			return 0
		}
		if x == 0 {
			continue
		}
		for i := length; i >= 0; i-- {
			for j := 1; j <= x; j++ {
				if (i - j) < 0 {
					break
				}
				dp[i] += dp[i-j] / t.F[j]
			}
		}
	}
	return dp[length]
}

func (t *Test) run() {
	if t.oj {
		t.is = os.Stdin
	} else {
		t.is = strings.NewReader(t.INPUT)
	}
	t.out = bufio.NewWriter(os.Stdout)

	s := time.Now()
	t.solve()
	t.out.Flush()
	t.tr(fmt.Sprintf("%dms", time.Since(s).Nanoseconds()/1000000))
}

func main() {
	tst := &Test{
		INPUT:  "",
		inbuf:  make([]byte, 1024),
		lenbuf: 0,
		ptrbuf: 0,
		oj:     true,
	}
	tst.run()
}

func (t *Test) readByte() int {
	if t.lenbuf == -1 {
		panic("InputMismatchException")
	}
	if t.ptrbuf >= t.lenbuf {
		t.ptrbuf = 0
		n, err := t.is.Read(t.inbuf)
		if err != nil && err != io.EOF {
			panic("InputMismatchException")
		}
		t.lenbuf = n
		if t.lenbuf <= 0 {
			return -1
		}
	}
	b := int(t.inbuf[t.ptrbuf])
	t.ptrbuf++
	return b
}

func (t *Test) isSpaceChar(c int) bool { return !(c >= 33 && c <= 126) }

func (t *Test) skip() int {
	var b int
	for {
		b = t.readByte()
		if b == -1 || !t.isSpaceChar(b) {
			break
		}
	}
	return b
}

func (t *Test) nd() float64 {
	v, _ := strconv.ParseFloat(t.ns(), 64)
	return v
}

func (t *Test) nc() rune { return rune(t.skip()) }

func (t *Test) ns() string {
	b := t.skip()
	var sb strings.Builder
	for !t.isSpaceChar(b) {
		sb.WriteRune(rune(b))
		b = t.readByte()
	}
	return sb.String()
}

func (t *Test) nsN(n int) []rune {
	buf := make([]rune, n)
	b := t.skip()
	p := 0
	for p < n && !t.isSpaceChar(b) {
		buf[p] = rune(b)
		p++
		b = t.readByte()
	}
	if n == p {
		return buf
	}
	return buf[:p]
}

func (t *Test) nm(n, m int) [][]rune {
	mp := make([][]rune, n)
	for i := 0; i < n; i++ {
		mp[i] = t.nsN(m)
	}
	return mp
}

func (t *Test) na(n int) []int {
	a := make([]int, n)
	for i := 0; i < n; i++ {
		a[i] = t.ni()
	}
	return a
}

func (t *Test) ni() int {
	num := 0
	var b int
	minus := false
	for {
		b = t.readByte()
		if b == -1 || (b >= '0' && b <= '9') || b == '-' {
			break
		}
	}
	if b == '-' {
		minus = true
		b = t.readByte()
	}

	for {
		if b >= '0' && b <= '9' {
			num = num*10 + (b - '0')
		} else {
			if minus {
				return -num
			}
			return num
		}
		b = t.readByte()
	}
}

func (t *Test) nl() int64 {
	var num int64 = 0
	var b int
	minus := false
	for {
		b = t.readByte()
		if b == -1 || (b >= '0' && b <= '9') || b == '-' {
			break
		}
	}
	if b == '-' {
		minus = true
		b = t.readByte()
	}

	for {
		if b >= '0' && b <= '9' {
			num = num*10 + int64(b-'0')
		} else {
			if minus {
				return -num
			}
			return num
		}
		b = t.readByte()
	}
}

func (t *Test) tr(o ...interface{}) {
	if !t.oj {
		fmt.Println(o...)
	}
}
